<template><div class="space-y-4"><div class="grid gap-3 md:grid-cols-2"><el-input-number v-model="age" :min="1" placeholder="年龄"/><el-input-number v-model="weight" :min="1" placeholder="体重（kg）"/><el-input-number v-model="height" :min="50" placeholder="身高（cm）"/><el-select v-model="gender"><el-option label="男性" value="male"/><el-option label="女性" value="female"/></el-select><el-select v-model="activity"><el-option v-for="x in activities" :key="x.value" :label="x.label" :value="x.value"/></el-select></div><el-button size="small" type="primary" @click="calculate">计算</el-button><div v-if="bmr" class="grid gap-3 md:grid-cols-2"><el-alert :title="`基础代谢：${bmr} kcal/天`" type="success" :closable="false"/><el-alert :title="`每日消耗：${tdee} kcal/天`" type="info" :closable="false"/></div></div></template>
<script setup lang="ts">import { ref } from 'vue';const age=ref(30),weight=ref(60),height=ref(170),gender=ref('male'),activity=ref(1.2),bmr=ref(0),tdee=ref(0);const activities=[{label:'久坐',value:1.2},{label:'轻度运动',value:1.375},{label:'中度运动',value:1.55},{label:'高强度运动',value:1.725}];const calculate=()=>{bmr.value=Math.round(10*weight.value+6.25*height.value-5*age.value+(gender.value==='male'?5:-161));tdee.value=Math.round(bmr.value*activity.value)}</script>
